//! Part 2: `string_enum!`, an enum with its text form.

use std::fmt;

/// Error returned by `FromStr` for types generated by [`string_enum!`].
///
/// `Display` reads `unknown <type_name> `<input>``.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnknownVariant {
    /// Name of the generated enum, e.g. `"JobState"`.
    pub type_name: &'static str,
    /// The rejected input, verbatim.
    pub input: String,
}

impl fmt::Display for UnknownVariant {
    fn fmt(&self, _f: &mut fmt::Formatter<'_>) -> fmt::Result {
        todo!("UnknownVariant: Display")
    }
}

impl std::error::Error for UnknownVariant {}

/// Generates a fieldless enum with a text form for each variant.
///
/// ```text
/// string_enum! {
///     /// docs (passed through)
///     pub enum JobState {
///         /// docs (passed through)
///         Queued = "queued",
///         Running = "running",
///     }
/// }
/// ```
///
/// Generated items:
/// - `#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]` on the enum, plus any
///   attributes the caller wrote.
/// - `pub const ALL: &'static [Self]`, every variant in declaration order.
/// - `pub const fn as_str(&self) -> &'static str`, the literal for that variant.
/// - `Display`, which writes `as_str()`.
/// - `FromStr`, exact and case-sensitive, with `Err = UnknownVariant`.
#[macro_export]
macro_rules! string_enum {
    (
        $(#[$meta:meta])*
        $vis:vis enum $name:ident {
            $( $(#[$variant_meta:meta])* $variant:ident = $text:literal ),+ $(,)?
        }
    ) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        $vis enum $name {
            $( $(#[$variant_meta])* $variant, )+
        }

        impl $name {
            /// Every variant, in declaration order. (Stub: empty.)
            $vis const ALL: &'static [Self] = &[];

            /// The text form of this variant.
            $vis const fn as_str(&self) -> &'static str {
                panic!("string_enum!: as_str")
            }
        }

        impl ::core::fmt::Display for $name {
            fn fmt(&self, _f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                todo!("string_enum!: Display")
            }
        }

        impl ::core::str::FromStr for $name {
            type Err = $crate::UnknownVariant;

            fn from_str(_s: &str) -> ::core::result::Result<Self, Self::Err> {
                todo!("string_enum!: FromStr")
            }
        }
    };
}
